import{_ as r,l as a,o as n,b as d,q as p,d as e,f as o,m as l}from"./chunks/framework.Tf23FRXt.js";const i="/assets/886.BXo3MPhr.jpg",B=JSON.parse('{"title":"卢比坎特歼灭战","description":"","frontmatter":{},"headers":[],"relativePath":"duty/886.htm.md","filePath":"duty/886.md","lastUpdated":1791098838000}'),m={name:"duty/886.htm.md"};function u(S,t,_,O,f,T){const s=a("Role");return n(),d("div",null,[t[5]||(t[5]=p('<h1 id="卢比坎特歼灭战" tabindex="-1">卢比坎特歼灭战</h1><div class="guide cols2"><div class="guide col"><img src="'+i+'" width="350px"><p>图片来自<a href="https://nowff14.blogspot.com/2023/01/Rubicante.html" target="_blank" rel="noreferrer">いまさら攻略 FF14</a></p></div><div class="guide col grow"><p>核心机制为<mark>炼狱朱炎</mark>，BOSS 读条后，场地周围出现 8 个魔法阵，地面上变成红紫色圈，并且出现连线。但是仔细观察的话，BOSS 脚下仅有一根连线，与 BOSS 连线的魔法阵在读条结束后，会立起并放出三角形 AOE。</p><p>第一次只要找到与 BOSS 连线的魔法阵，并站到这个魔法阵两侧躲避即可。</p><p>第三次开始，紫色的地板会随箭头所示方向旋转 45°。对于歼灭战这个副本来说，可以不用考虑旋转后的魔法阵和线，只要站在一开始连线的魔法阵下方，就一定是安全的。</p></div></div><p>其他需要注意的机制：</p>',3)),e("ul",null,[e("li",null,[t[0]||(t[0]=o("烈火赤灭爪：BOSS 脚下出现旋转的箭头，箭头停下后，立刻沿箭头方向放直线 AOE，然后向两侧扩散 2 次。这个机制非常快，不是很好躲，如果你第一下躲开了，第一下 AOE 后立刻向已经炸过的区域（BOSS 脚下）移动；如果第一下没躲开，站在原地不要乱跑。",-1)),l(s,{name:"healer"}),t[1]||(t[1]=o("治疗注意抬血。",-1))]),t[4]||(t[4]=e("li",null,"灭土烧尽：读条后点所有玩家不可回避的直线 AOE，第一次伤害后，飞到场外的分身会向场内再次造成直线 AOE。最好的处理方法是第一次点名时 8 人两两相对（8 方分散）引导，如果一开始大家站得比较乱，会导致第二次 AOE 没有回避空间，此时应注意向场地边缘移动（场地边缘可能会存在安全空间）。",-1)),e("li",null,[t[2]||(t[2]=o("双炎流：点名 2",-1)),l(s,{name:"tank"}),t[3]||(t[3]=o("T 巨大扇形 AOE，两名 T 在前半场分左右站，其他人在后半场躲避即可（如果场面混乱到处是人，T 尽量不要乱动，让人群躲 T）。",-1))])]),t[6]||(t[6]=e("p",null,"其他出啥躲啥即可。",-1))])}const g=r(m,[["render",u]]);export{B as __pageData,g as default};
